    return np.column_stack([d[n] for n in names])
def run(names):
    best=None
    for w0 in np.linspace(0.38,0.44,7):
        f=lambda p: mk(p[0],names)@p[1:]-dv_dt
        X=mk(w0,names); c0=np.linalg.lstsq(X,dv_dt,rcond=None)[0]
